with exploded as (select id, customer_id, li_item.product_id, li_item.promo from (select id, customer_id, explode_outer(items) as li_item from carts) e) select promo, product_id, avg(product_id) as avg_product_id, count(*) as cnt, count(*) filter (where promo = 'WELCOME5') as welcome5_rows, avg(product_id) as avg_product_id_2, avg(product_id) filter (where promo = 'WELCOME5') as welcome5_avg_product_id from exploded group by promo, product_id having avg_product_id > 0 order by product_id desc nulls last
